    seen.add(order.id);
    if (order.status === 'refunded') continue;

    // A NaN customerId never matched an existing group (=== lookup), so keep it ungrouped.
    const key = order.customerId;
    let group = key === key ? groupsById.get(key) : undefined;
    if (!group) {
      group = { customerId: order.customerId, spendCents: 0, orderCount: 0, firstOrderAt: order.createdAt };
      groups.push(group);
      if (key === key) groupsById.set(key, group);
