  // byRank is a total order over distinct customers, so one sort at the end gives the
  // same leaderboard as re-sorting after every order.
  groups.sort(byRank);
  return groups
    .filter((g) => g.spendCents > 0)
    .slice(0, limit)
    .map((g, i) => ({ rank: i + 1, ...g }));
}

